static void
test_parses_long_ipv6 (void)
{
   char *host;
   char *host_and_port;
   size_t len;
   char *uri_str;
   mongoc_uri_t *uri;
   const mongoc_host_list_t *hosts;

   /* IPv6 literal of exactly maximum permitted length. */
   len = BSON_HOST_NAME_MAX - 2;
   host = bson_malloc (len + 1);
   memset (host, 'a', len);
   host[4] = ':';
   host[len] = '\0';
   host_and_port = bson_strdup_printf ("[%s]:12345", host);
   uri_str = bson_strdup_printf ("mongodb://%s", host_and_port);
   uri = mongoc_uri_new (uri_str);
   ASSERT (uri);
   hosts = mongoc_uri_get_hosts (uri);
   ASSERT_CMPSTR (hosts->host, host);
   ASSERT_CMPSTR (hosts->host_and_port, host_and_port);
   ASSERT_CMPINT (hosts->port, ==, 12345);

   mongoc_uri_destroy (uri);
   bson_free (uri_str);
   bson_free (host_and_port);
   bson_free (host);

   /* IPv6 literal length exceeds maximum permitted by one. */
   len++;
   host = bson_malloc (len + 1);
   memset (host, 'a', len);
   host[4] = ':';
   host[len] = '\0';
   host_and_port = bson_strdup_printf ("[%s]", host);
   uri_str = bson_strdup_printf ("mongodb://%s:27017", host_and_port);

   capture_logs (true);
   ASSERT (!mongoc_uri_new (uri_str));
   ASSERT_CAPTURED_LOG ("mongoc_uri_new", MONGOC_LOG_LEVEL_ERROR, "too long");

   clear_captured_logs ();
   ASSERT (!mongoc_uri_new_for_host_port (host_and_port, 27017));
   ASSERT_CAPTURED_LOG ("mongoc_uri_new", MONGOC_LOG_LEVEL_ERROR, "too long");

   bson_free (uri_str);
   bson_free (host_and_port);
   bson_free (host);
}

