static inline bool
mongoc_parse_port (uint16_t *port, const char *str)
{
   long p;
   char *end;
   BSON_ASSERT (port);
   BSON_ASSERT (str);
   if (*str == '\0') {
      return false;
   }
   p = strtol (str, &end, 10);
   if (*end != '\0') {
      return false;
   }
   if (p < 1 || p > 65535) {
      return false;
   }
   *port = (uint16_t) p;
   return true;
}

