#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>

#define CHECK(cond)                                                          \
   do {                                                                      \
      if (!(cond)) {                                                         \
         fprintf (stderr, "FAIL line %d: %s\n", __LINE__, #cond);            \
         exit (1);                                                           \
      }                                                                      \
   } while (0)

int
main (void)
{
   mongoc_host_list_t hl;
   bson_error_t err = {0};
   size_t len;
   char *host;
   char *host_and_port;
   char *expected_hap;
   unsigned int fails = 0;

   /* --- Case 1: largest permitted IPv6 literal (BSON_HOST_NAME_MAX - 2) --- */
   len = BSON_HOST_NAME_MAX - 2;
   host = bson_malloc (len + 1);
   memset (host, 'a', len);
   host[4] = ':';
   host[len] = '\0';

   expected_hap = bson_strdup_printf ("[%s]:12345", host);
   host_and_port = bson_strdup_printf ("%s", expected_hap);

   memset (&hl, 0, sizeof hl);
   if (!_mongoc_host_list_from_string_with_err (&hl, host_and_port, &err)) {
      fprintf (stderr, "FAIL: max-length IPv6 rejected: %s\n", err.message);
      fails++;
   } else {
      CHECK (hl.port == 12345);
      CHECK (hl.family == AF_INET6);
      CHECK (strcmp (hl.host, host) == 0);
      CHECK (strcmp (hl.host_and_port, expected_hap) == 0);
      printf ("PASS: max-length IPv6 literal parsed OK\n");
      printf ("   host_and_port = %s\n", hl.host_and_port);
   }

   bson_free (host_and_port);
   bson_free (expected_hap);
   bson_free (host);

   /* --- Case 2: one character past max (BSON_HOST_NAME_MAX - 1) --- */
   len++;
   host = bson_malloc (len + 1);
   memset (host, 'a', len);
   host[4] = ':';
   host[len] = '\0';
   host_and_port = bson_strdup_printf ("[%s]:27017", host);

   memset (&err, 0, sizeof err);
   memset (&hl, 0, sizeof hl);
   if (_mongoc_host_list_from_string_with_err (&hl, host_and_port, &err)) {
      fprintf (stderr, "FAIL: over-max IPv6 literal was accepted\n");
      fails++;
   } else {
      if (strstr (err.message, "too long")) {
         printf ("PASS: over-max IPv6 literal rejected (\"%s\")\n",
                 err.message);
      } else {
         fprintf (stderr, "FAIL: wrong error message: \"%s\"\n", err.message);
         fails++;
      }
   }

   bson_free (host_and_port);
   bson_free (host);

   /* --- Case 3: sanity - normal short IPv6 still parses --- */
   memset (&err, 0, sizeof err);
   memset (&hl, 0, sizeof hl);
   if (_mongoc_host_list_from_string_with_err (
          &hl, "[fe80::1]:1234", &err)) {
      CHECK (hl.port == 1234);
      CHECK (hl.family == AF_INET6);
      CHECK (strcmp (hl.host, "fe80::1") == 0);
      CHECK (strcmp (hl.host_and_port, "[fe80::1]:1234") == 0);
      printf ("PASS: short IPv6 literal still parses OK\n");
   } else {
      fprintf (stderr, "FAIL: short IPv6 rejected: %s\n", err.message);
      fails++;
   }

   if (fails) {
      fprintf (stderr, "%u failure(s)\n", fails);
      return 1;
   }
   printf ("ALL CHECKS PASSED\n");
   return 0;
}

