    end = len(lines)+1
    for other in funcs:
        if other['start'] > start:
            end = min(end, other['start'])
    # collect events
    events = []
    for j in range(start, end):
        line = lines[j-1]
        if re.match(r'\s*/\* Start Example \d+ Post \*/', line):
            events.append((j, 'StartPost'))
        elif re.match(r'\s*/\* End Example \d+ Post \*/', line):
            events.append((j, 'EndPost'))
        elif re.match(r'^\s*done:\s*$', line):
            events.append((j, 'done'))
        elif re.match(r'\s*/\* Start Example \d+ \*/', line):
            events.append((j, 'StartEx'))
        elif re.match(r'\s*/\* End Example \d+ \*/', line):
            events.append((j, 'EndEx'))
