import re

def per_func(fname):
    with open(fname) as f:
        lines = f.readlines()
    funcs = []
    cur = None
    for i, line in enumerate(lines, 1):
        m = re.match(r'^test_example_(\d+) \(mongoc_database_t \*db\)', line)
